#include <stdio.h>
#include <stdlib.h>

static int cmp(const void *a, const void *b) {
    return (*(const int *)a > *(const int *)b) - (*(const int *)a < *(const int *)b);
}

int main(void) {
    int nums[] = {5, 3, 8, 1};
    int n = sizeof nums / sizeof nums[0];
    qsort(nums, n, sizeof nums[0], cmp);
    for (int i = 0; i < n; i++) printf(i ? " %d" : "%d", nums[i]);
    printf("\n");
    return 0;
}

