    std::string s = "hello";
    std::transform(s.begin(), s.end(), s.begin(), [](unsigned char c) { return std::toupper(c); });
    std::cout << s << std::endl;
}

package main

import (
	"fmt"
	"strings"
)

func main() {
	fmt.Println(strings.ToUpper("hello"))
}

public class Main {
    public static void main(String[] args) {
        System.out.println("hello".toUpperCase());
    }
}
